content:
/* Reset & Universal Overrides */

* {
box-shadow: none !important;
}

/* Modal Container Base - Mobile Default (< 768px): Floating at bottom */
.install-app-modal {
position: fixed;
z-index: 9999;
width: 320px;
max-width: calc(100vw - 1em);
bottom: 0.5em;
left: 0.5em;
right: 0.5em;
top: auto;
margin-left: auto;
margin-right: auto;
transition: opacity 0.25s ease-in-out, transform 0.25s ease-in-out;

}

.install-app-modal.hidden-prompt {
opacity: 0;
pointer-events: none;
transform: translateY(20px);
}

@media (min-width: 768px) and (max-width: 1023px) {
.install-app-modal {
bottom: 0.5em;
right: 0.5em;
left: auto;
top: auto;
margin-left: 0;
margin-right: 0;
}
}

@media (min-width: 1024px) {
.install-app-modal {
top: 0.5em;
right: 0.5em;
left: auto;
bottom: auto;
margin-left: 0;
margin-right: 0;
}
}

.install-btn-accent {
background-color: var(--theme-accent, #22c55e);
}

.install-btn-accent:hover {
filter: brightness(1.1);
}

.install-btn-accent:active {
transform: scale(0.98);
}

const CACHE_NAME = 'edurise-pwa-v1';
const ASSETS = [
    './',
    './index.html',
    './view.html',
    './create_course.html',
    './1000760180.png',
    './pwa.css',
    './pwa.js',
    './manifest.json'
];

self.addEventListener('install', (event) => {
    event.waitUntil(
        caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS))
    );
    self.skipWaiting();
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        caches.keys().then((keys) => {
            return Promise.all(
                keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
            );
        })
    );
    self.clients.claim();
});

self.addEventListener('fetch', (event) => {
    event.respondWith(
        caches.match(event.request).then((cachedResponse) => {
            return cachedResponse || fetch(event.request);
        })
    );
});

